<script setup lang="ts">
import{dentistCommand,parseDentistCommand,sameDentistCommand}from'./dentist-command';
import{useSalesScope}from'./use-sales-scope';
import{ref,computed,onMounted,watch}from'vue';import{Stethoscope,History,Eye,Save,X,RefreshCw,Plus}from'@lucide/vue';
import DentistRecovery from './DentistRecovery.vue';
import{dentistPendingTarget,validDentistSaved}from'./dentist-pending-status';
import QualificationPanel from './QualificationPanel.vue';
const qualificationBusy=ref(false);
const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized']),clinics=ref<any[]>([]),clinic=ref(''),rows=ref<any[]>([]),next=ref<string|null>(null),detail=ref<any>(null),history=ref<any[]>([]),historyNext=ref<string|null>(null),practiceHistory=ref<any[]>([]),functions=ref<string[]>([]),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),mode=ref(''),form=ref<any>({}),preview=ref<any>(null),previewSignature=ref(''),pending=ref<any>(null),key=()=> 'adc.dentistPending:'+props.staff.accountId;
const labels:Record<string,string>={profile:'内部基本资料',skills:'专业技能',public:'患者端公开介绍',practice:'诊所执业期间'},time=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚无办理时点',short=(id:string)=>id.slice(0,8).toUpperCase(),clinicName=(id:string)=>clinics.value.find(c=>c.id===id)?.name||short(id),canManage=computed(()=>functions.value.includes('dentist.manage'));
const historyTotal=ref<number|null>(null),historyAsOf=ref(''),practiceNext=ref<string|null>(null),practiceTotal=ref<number|null>(null),practiceAsOf=ref('');
const search=ref(''),directoryTotal=ref<number|null>(null),directoryAsOf=ref('');
watch(search,()=>{selection.value++;rows.value=[];next.value=null;directoryTotal.value=null;directoryAsOf.value='';clearView();loading.value=false;},{flush:'sync'});
const selection=ref(0),editGeneration=ref(0),identity=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId]),authScope=useSalesScope(identity),viewScope=useSalesScope(()=>JSON.stringify([identity(),clinic.value,selection.value]));
function clearView(){detail.value=null;clearHistory('profile');clearHistory('practice');mode.value='';form.value={};preview.value=null;previewSignature.value='';qualificationBusy.value=false;}
watch(clinic,()=>{selection.value++;busy.value=false;rows.value=[];next.value=null;directoryTotal.value=null;directoryAsOf.value='';clearView();},{flush:'sync'});
watch(()=>JSON.stringify([mode.value,Object.fromEntries(Object.entries(form.value).filter(([k])=>!['checked','confirmImpact'].includes(k)))]),()=>{editGeneration.value++;form.value.checked=false;form.value.confirmImpact=false;preview.value=null;previewSignature.value='';},{flush:'sync'});
class ApiError extends Error{constructor(readonly status:number,m:string){super(m);}}
async function api(path:string,body?:any,current:()=>boolean=()=>true){const own=authScope.capture(),c=new AbortController(),timer=setTimeout(()=>c.abort(),20000);try{const r=await fetch('/api/v1/dentists'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:c.signal}),b=await r.json();if(!r.ok){if(r.status===401&&own()&&current())emit('unauthorized');throw new ApiError(r.status,b.message||'牙医资料请求失败。');}return b;}finally{clearTimeout(timer);}}
const explain=(e:unknown)=>e instanceof Error?e.message:'请求失败。';
async function initialize(){const current=authScope.begin('initialize');loading.value=true;error.value='';try{restoreCache();const b=await api('/bootstrap',undefined,current);if(!current())return;clinics.value=b.clinics;functions.value=b.functions;clinic.value=b.clinics.some((c:any)=>c.id===clinic.value)?clinic.value:b.clinics[0]?.id||'';if(clinic.value)await list();}catch(e){if(current())error.value=explain(e);}finally{if(current.active())loading.value=false;}}
async function list(more=false){if(more&&!next.value)return;const point=directoryAsOf.value;if(!more){selection.value++;rows.value=[];next.value=null;directoryTotal.value=null;directoryAsOf.value='';clearView();}const current=viewScope.begin('list');loading.value=true;error.value='';try{const params=new URLSearchParams({clinicId:clinic.value,q:search.value.trim()});if(more)params.set('cursor',next.value!);const r=await api('/directory?'+params,undefined,current);if(!current())return;if(more&&r.asOf!==point)throw new ApiError(409,'目录读取时点已变化，请重新读取。');rows.value=more?[...rows.value,...r.items]:r.items;next.value=r.next;directoryTotal.value=r.total??r.items.length;directoryAsOf.value=r.asOf??'';}catch(e:any){if(current()){if([401,403,409].includes(e.status)){selection.value++;rows.value=[];next.value=null;directoryTotal.value=null;directoryAsOf.value='';clearView();loading.value=false;}error.value=explain(e);}}finally{if(current.active())loading.value=false;}}

function readFailure(e:any,current:()=>boolean){if(!current())return;if([401,403].includes(e.status)){selection.value++;clearView();loading.value=false;}error.value=explain(e);}
function clearHistory(kind:'profile'|'practice'){if(kind==='profile'){history.value=[];historyNext.value=null;historyTotal.value=null;historyAsOf.value='';}else{practiceHistory.value=[];practiceNext.value=null;practiceTotal.value=null;practiceAsOf.value='';}}
async function historyPage(kind:'profile'|'practice',more=false){
 if(!detail.value)return;if(kind==='profile'&&!detail.value.canEditGlobal){clearHistory(kind);return;}
 const cursor=kind==='profile'?historyNext.value:practiceNext.value,point=kind==='profile'?historyAsOf.value:practiceAsOf.value;if(more&&!cursor)return;if(!more)clearHistory(kind);
 const id=detail.value.doctor.id,current=viewScope.begin(kind+'-history',()=>detail.value?.doctor.id||''),params=new URLSearchParams({kind});if(kind==='practice')params.set('clinicId',clinic.value);if(more)params.set('cursor',cursor!);
 try{const r=await api('/'+id+'/history-page?'+params,undefined,current);if(!current())return;if(more&&r.asOf!==point)throw new ApiError(409,'历史读取时点已变化，请重新读取。');if(kind==='profile'){history.value=more?[...history.value,...r.items]:r.items;historyNext.value=r.next??null;historyTotal.value=r.total??r.items.length;historyAsOf.value=r.asOf??'';}else{practiceHistory.value=more?[...practiceHistory.value,...r.items]:r.items;practiceNext.value=r.next??null;practiceTotal.value=r.total??r.items.length;practiceAsOf.value=r.asOf??'';}}
 catch(e:any){if(!current())return;if(e.status===409)clearHistory(kind);readFailure(e,current);}
}
async function loadHistory(more=false){return historyPage('profile',more);}
async function loadPractice(more=false){return historyPage('practice',more);}

async function view(id:string){selection.value++;clearView();const current=viewScope.begin('detail');loading.value=true;error.value='';try{const d=await api('/'+id,undefined,current);if(!current())return;detail.value=d;await Promise.all([loadHistory(),loadPractice()]);}catch(e){if(current()){clearView();error.value=explain(e);}}finally{if(current.active())loading.value=false;}}

function open(branch:string,p?:any){if(cacheBlocked.value||pending.value)return;mode.value=branch;preview.value=null;previewSignature.value='';error.value='';const d=detail.value.doctor;if(branch==='profile')form.value={version:d.version,name:d.name,contactInfo:d.contactInfo||'',personalProfile:d.personalProfile||'',reason:'',checked:false,confirmImpact:false};if(branch==='skills')form.value={version:d.version,skillsText:d.skills.join('\n'),reason:'',checked:false,confirmImpact:false};if(branch==='public')form.value={version:d.version,publicName:d.publicName||'',publicSpecialty:d.publicSpecialty||'',publicIntro:d.publicIntro||'',publicEnabled:d.publicEnabled,reason:'',checked:false,confirmImpact:false};if(branch==='practice')form.value={version:p?Number(p.row_version):d.version,practiceId:p?.practice_id||null,clinicId:p?.clinic_id||clinic.value,validFrom:p?.valid_from||new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'}),validTo:p?.valid_to||'',reason:'',checked:false,confirmImpact:false};}
function body(){const f=form.value,base={version:f.version,reason:f.reason};return mode.value==='profile'?{...base,name:f.name,contactInfo:f.contactInfo||null,personalProfile:f.personalProfile||null}:mode.value==='skills'?{...base,skills:f.skillsText.split('\n').map((x:string)=>x.trim()).filter(Boolean).sort()}:mode.value==='public'?{...base,publicName:f.publicName||null,publicSpecialty:f.publicSpecialty||null,publicIntro:f.publicIntro||null,publicEnabled:f.publicEnabled}:{...base,clinicId:f.clinicId,practiceId:f.practiceId,validFrom:f.validFrom,validTo:f.validTo||null};}
const previewCurrent=computed(()=>!!preview.value&&previewSignature.value===JSON.stringify(body())),impactCount=computed(()=>preview.value?preview.value.affected.schedules.length+preview.value.affected.appointments.length:0);
async function inspect(){if(cacheBlocked.value||!detail.value||busy.value||pending.value)return;const input=body(),signature=JSON.stringify(input),path='/'+detail.value.doctor.id+'/'+mode.value+'/preview',current=viewScope.begin('preview',()=>JSON.stringify([detail.value?.doctor.id,mode.value,body(),editGeneration.value]));busy.value=true;error.value='';preview.value=null;previewSignature.value='';form.value.checked=false;form.value.confirmImpact=false;try{const r=await api(path,input,current);if(current()){preview.value=r;previewSignature.value=signature;}}catch(e){if(current()){preview.value=null;previewSignature.value='';error.value=explain(e);}}finally{if(current.active())busy.value=false;}}
function recoveryAccessLost(){selection.value++;rows.value=[];next.value=null;directoryTotal.value=null;directoryAsOf.value='';clearView();loading.value=false;error.value='当前原提交读取范围已失效，已清除牙医详情，请保留原请求。';}
const cacheBlocked=ref(false),cacheError=ref('');
const samePending=sameDentistCommand;
function restoreCache(){const known=pending.value?.known?pending.value:null;cacheBlocked.value=false;cacheError.value='';pending.value=null;try{const raw=sessionStorage.getItem(key());if(raw){const stored=parseDentistCommand(raw,props.staff);pending.value=known&&samePending(known,stored)?known:stored;}else if(known)pending.value=known;}catch{pending.value=known;cacheBlocked.value=true;cacheError.value='原牙医缓存损坏、身份不符或无法读取；已保留记录并阻止新保存。';}}
function keep(p:any){const raw=sessionStorage.getItem(key());if(raw&&!samePending(parseDentistCommand(raw,props.staff),p))throw Error('本机已有另一笔请求，未覆盖。');sessionStorage.setItem(key(),JSON.stringify(p));}
function markKnown(p:any,phase='confirmed'){if(!samePending(pending.value,p))throw Error('本机已有另一笔请求，未清理。');pending.value={...p,phase,known:true};try{keep(pending.value);}catch{cacheError.value='原结果已知，但本机状态未写入；请只清理提示，重新加载后先只读核实。';}}
function cleanup(p:any){const raw=sessionStorage.getItem(key());if(raw&&!samePending(parseDentistCommand(raw,props.staff),p))throw Error('本机记录已变化，未删除另一笔请求。');sessionStorage.removeItem(key());pending.value=null;cacheError.value='';}
function clearVerified(value:any){if(busy.value||cacheBlocked.value)return;try{const p=dentistCommand(value,props.staff);if(!samePending(pending.value,p))return;if(!pending.value.known)markKnown(p);cleanup(p);notice.value='仅清理了本机提示，未重新保存。';}catch(e){cacheError.value=explain(e);}}
async function submit(value:any,retrying=false){
 if(busy.value||cacheBlocked.value)return;let p:any;
 try{p=dentistCommand(value,props.staff);if(p.known)return;}catch(e){error.value=explain(e);return;}
 try{if(pending.value&&!samePending(pending.value,p))throw Error('本机已有另一笔请求。');const raw=sessionStorage.getItem(key());if(raw){const stored=parseDentistCommand(raw,props.staff);if(stored.known||!samePending(stored,p))throw Error('本机已有其他或已知结果请求，未发送。');}}catch(e){cacheBlocked.value=true;cacheError.value=explain(e);return;}
 try{keep(p);}catch{cacheError.value='原请求未能写入本机，本次未发送；请恢复存储后再试。';return;}
 pending.value=p;const own=authScope.capture();busy.value=true;error.value='';let result:any=null;
 try{const r=await api(p.path,p.body,own);if(!own())return;validDentistSaved(p,r);result=r;
 }catch(e){if(!own())return;error.value=explain(e);mode.value='';if(e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==401&&!retrying){try{markKnown(p,'rejected');cleanup(p);}catch(clean){cacheError.value=explain(clean);}}else error.value+=' 原结果尚未核实，请保留原请求，先只读查询。';
 }finally{if(own())busy.value=false;}
 if(!own()||!result)return;
 mode.value='';markKnown(p);try{cleanup(p);}catch(e){cacheError.value=explain(e);return;}
 notice.value='原保存成功，版本 '+result.version+'；以下重新读取当前资料，排班与预约未自动改动。';
 try{await list();if(own()&&!error.value)await view(result.doctorId);if(own()&&error.value)error.value='原保存已成功，当前资料读取失败，请重新读取。 '+error.value;}catch(e){if(own())error.value='原保存已成功，请重新读取当前资料。 '+explain(e);}
}
async function save(){if(cacheBlocked.value||busy.value||pending.value||!previewCurrent.value)return;try{if(sessionStorage.getItem(key())){restoreCache();error.value='请先处理原本机记录，未发送新保存。';return;}}catch{cacheBlocked.value=true;cacheError.value='无法读取原记录，未发送新保存。';return;}await submit({path:'/'+detail.value.doctor.id+'/'+mode.value,body:{...body(),requestId:crypto.randomUUID(),impactToken:preview.value.impactToken,checked:form.value.checked,confirmImpact:form.value.confirmImpact}});}

watch(identity,()=>{clinics.value=[];functions.value=[];clinic.value='';rows.value=[];next.value=null;clearView();pending.value=null;busy.value=false;loading.value=false;error.value='';notice.value='';search.value='';directoryTotal.value=null;directoryAsOf.value='';void initialize();},{flush:'sync'});
defineExpose({refresh:initialize});onMounted(initialize);
</script>
<template><div class="dentist-workspace"><div v-if="cacheError" class="b-alert error" role="alert">{{cacheError}}<button class="b-button outline" :disabled="busy||loading" @click="restoreCache">重新读取本机记录</button></div><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div><DentistRecovery v-if="pending" :staff="staff" :pending="pending" :busy="busy" @clear="clearVerified" @retry="submit($event,true)" @unauthorized="emit('unauthorized')" @access-lost="recoveryAccessLost"/><section class="b-card dw-head"><div><div class="b-eyebrow">DENTIST FOUNDATION</div><h2><Stethoscope :size="25"/>牙医资料与执业</h2><p>同一员工统一识别，内部资料与公开介绍分别维护。</p></div><label>查询诊所<select v-model="clinic" :disabled="loading||busy||!!pending||cacheBlocked||qualificationBusy" @change="list()"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="b-button outline" :disabled="loading||busy" @click="initialize"><RefreshCw :size="17"/>重新读取</button></section>
<section class="b-card dw-block"><h3>本范围牙医</h3><div class="dw-query"><label>姓名、专业或编号<input v-model="search" maxlength="100" :disabled="busy||!!pending||qualificationBusy" placeholder="输入后点击查询"/></label><button class="b-button outline" :disabled="busy||loading" @click="list()">查询牙医</button></div><p v-if="directoryTotal!==null" class="b-help">已加载 {{rows.length}} / 共 {{directoryTotal}} 人</p><p v-else-if="!loading" class="b-help">条件已变化，请查询牙医。</p><div class="dw-doctors"><button v-for="d in rows" :key="d.id" class="dw-doctor" :class="{selected:detail?.doctor.id===d.id}" :disabled="loading||busy||!!pending||cacheBlocked||qualificationBusy" @click="view(d.id)"><span class="dw-avatar">{{d.name.slice(0,1)}}</span><div><strong>{{d.name}}</strong><small>{{d.specialty||'公开专业未登记'}} · {{d.published?'已发布介绍':'未发布介绍'}}</small><small>{{short(d.id)}} · v{{d.version}}</small></div></button></div><p v-if="directoryTotal===0&&!loading">本范围尚无已关联牙医；本批不新建员工。</p><button v-if="next" class="b-button outline" :disabled="loading||busy" @click="list(true)">继续加载牙医</button></section>
<template v-if="detail"><section class="b-card dw-block"><div class="dw-title"><div><h3>{{detail.doctor.name}} · 内部基本资料</h3><p>稳定身份 {{short(detail.doctor.id)}} · 当前专业资料 v{{detail.doctor.version}}</p></div><button v-if="canManage&&detail.canEditGlobal" class="b-button" :disabled="busy||loading||!!pending||cacheBlocked||qualificationBusy" @click="open('profile')">维护内部资料</button></div><p v-if="!detail.canEditGlobal" class="b-alert warning">这是共用牙医。全局资料、技能、公开介绍及其历史需具备全部关联诊所范围，本店执业期可按本店权限办理。</p><dl class="dw-fields"><div><dt>员工姓名</dt><dd>{{detail.doctor.name}}</dd></div><div><dt>内部联系方式</dt><dd>{{detail.doctor.contactInfo||'尚未登记'}}</dd></div><div><dt>内部个人资料</dt><dd>{{detail.doctor.personalProfile||'尚未登记'}}</dd></div><div><dt>最近专业维护</dt><dd>{{time(detail.doctor.editedAt)}}</dd></div></dl><p class="b-help">内部资料不自动发布到患者端，不调整任职、账号、诊疗或原业务归属。</p></section>
<section class="b-card dw-block"><div class="dw-title"><h3>专业技能</h3><button v-if="canManage&&detail.canEditGlobal" class="b-button outline" :disabled="busy||loading||!!pending||cacheBlocked||qualificationBusy" @click="open('skills')">维护技能集合</button></div><div class="dw-tags"><span v-for="s in detail.doctor.skills" :key="s">{{s}}</span><p v-if="!detail.doctor.skills.length">尚无明确登记的技能。</p></div><p class="b-help">技能、证书与公开介绍分别表达。已有资格记录{{detail.qualificationCount}}项；证书及附件在独立分支维护，不自动发布到患者端。</p></section>
<QualificationPanel v-if="functions.includes('dentist.qualification.read')&&detail.canEditGlobal" :key="identity()+detail.doctor.id+selection" :doctor-id="detail.doctor.id" :doctor-version="detail.doctor.version" :staff="staff" @unauthorized="emit('unauthorized')" @changed="detail.qualificationCount=$event" @busy-change="qualificationBusy=$event"/><section class="b-card dw-block"><div class="dw-title"><h3><Eye :size="20"/>患者端公开介绍</h3><button v-if="canManage&&detail.canEditGlobal" class="b-button" :disabled="busy||loading||!!pending||cacheBlocked||qualificationBusy" @click="open('public')">维护公开介绍</button></div><div class="dw-public"><span class="b-pill" :class="{active:detail.doctor.publicEnabled}">{{detail.doctor.publicEnabled?'允许患者端显示':'未发布'}}</span><h3>{{detail.doctor.publicName||'公开姓名未填写'}}</h3><strong>{{detail.doctor.publicSpecialty||'公开专业未填写'}}</strong><p>{{detail.doctor.publicIntro||'公开介绍未填写'}}</p></div><p class="b-help">仅以上公开姓名、专业和介绍按发布状态展示，不把内部联系、个人资料、技能或证书附件自动拼入。暂停公开不取消原预约、不停用员工账号。</p></section>
<section class="b-card dw-block"><div class="dw-title"><h3>诊所执业关系</h3><button v-if="canManage&&detail.canEditGlobal" class="b-button outline" :disabled="busy||loading||!!pending||cacheBlocked||qualificationBusy" @click="open('practice')"><Plus :size="17"/>新增本店执业期</button></div><article v-for="p in detail.practices" :key="p.practice_id" class="dw-history"><div class="dw-title"><strong>{{p.clinic_name}} · v{{p.row_version}}</strong><button v-if="canManage&&p.clinic_id===clinic&&p.practice_arrangement==='enabled'" class="b-button outline small" :disabled="busy||loading||!!pending||cacheBlocked||qualificationBusy" @click="open('practice',p)">维护有效至</button></div><p>{{p.valid_from}} 至 {{p.valid_to||'无固定结束日'}}（含两端） · {{p.practice_arrangement==='enabled'?'已启用关系':'其他既有状态'}}</p><small>关系 {{short(p.practice_id)}} · 修改 {{time(p.updated_at)}}</small></article><p class="b-help">只显示当前有权查看的关系。有效至包含当天；本批原开始日固定，不追溯改写已结束关系。立即停诊由排班办理，关系不自动建立服务、排班或权限。</p></section>
<section v-if="detail.canEditGlobal" class="b-card dw-block"><h3><History :size="20"/>专业资料完整原版</h3><p v-if="historyTotal!==null" class="b-help">已加载 {{history.length}} / 共 {{historyTotal}} 版</p><p v-if="historyTotal===0">首次维护时会纳入原v1资料，并保留完整技能集合。</p><article v-for="h in history" :key="h.version" class="dw-history"><div class="dw-title"><strong>v{{h.version}} · {{h.name}}</strong><small>{{h.initialCapture?'首次纳入的原资料':labels[h.branch]||'专业资料版本'}}</small></div><p>内部：{{h.contactInfo||'联系方式未登记'}} · {{h.personalProfile||'个人资料未登记'}}</p><p>技能：{{h.skills.join('、')||'未登记'}}</p><p>公开：{{h.publicEnabled?'已发布':'未发布'}} · {{h.publicName||'未填写'}} · {{h.publicSpecialty||'未填写'}} · {{h.publicIntro||'未填写'}}</p><small>原资料时点 {{time(h.editedAt)}} · 本次留存 {{time(h.registeredAt)}} · {{h.actorName}}</small><p>依据：{{h.reason}}</p></article><button v-if="historyNext" class="b-button outline" :disabled="busy||loading" @click="loadHistory(true)">继续加载专业原版</button></section>
<section class="b-card dw-block"><h3>本店执业原版</h3><p v-if="practiceTotal!==null" class="b-help">已加载 {{practiceHistory.length}} / 共 {{practiceTotal}} 版</p><p v-if="practiceTotal===0">本店尚无关系变更原版。</p><article v-for="h in practiceHistory" :key="h.practice_revision_id" class="dw-history"><strong>{{short(h.practice_id)}} · v{{h.version_no}} · {{h.valid_from}} 至 {{h.valid_to||'无固定终点'}}</strong><p>{{h.reason}}</p><small>原资料 {{time(h.updated_at)}} · 本次留存 {{time(h.occurred_at)}} · {{h.actor_name}}</small><p v-if="h.legacyImpactUnavailable" class="b-help">旧影响资料无法按当前格式展示，请核对原办理记录。</p><details v-if="h.affected"><summary>本版受影响安排：排班{{h.affected.schedules.length}}、预约{{h.affected.appointments.length}}</summary><article v-for="x in [...h.affected.schedules,...h.affected.appointments]" :key="x.id"><p>{{short(x.id)}} · {{time(x.startsAt)}} — {{time(x.endsAt)}} · v{{x.version}}</p></article></details></article><button v-if="practiceNext" class="b-button outline" :disabled="busy||loading" @click="loadPractice(true)">继续加载执业原版</button></section></template>
<div v-if="mode" class="b-backdrop"><form class="b-dialog dw-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭牙医资料办理" :disabled="busy||!!pending||cacheBlocked" @click="mode='' "><X :size="22"/></button><div class="b-eyebrow">DENTIST FOUNDATION</div><h2>{{labels[mode]}}</h2><p>{{detail.doctor.name}} · {{short(detail.doctor.id)}} · 基准v{{form.version}}</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><template v-if="mode==='profile'"><label>员工姓名<input v-model="form.name" required maxlength="100" :disabled="busy||!!pending||cacheBlocked"/></label><label>内部联系方式<input v-model="form.contactInfo" maxlength="500" :disabled="busy||!!pending||cacheBlocked"/></label><label>内部个人资料<textarea v-model="form.personalProfile" rows="3" maxlength="3000" :disabled="busy||!!pending||cacheBlocked"/></label></template><template v-else-if="mode==='skills'"><label>技能集合（每行一项）<textarea v-model="form.skillsText" rows="5" :disabled="busy||!!pending||cacheBlocked"/></label><p class="b-help">完整替换本分支技能，空集合表示明确清空；其他资料和证书不动。最多50项。</p></template><template v-else-if="mode==='public'"><label>公开姓名<input v-model="form.publicName" maxlength="100" :required="form.publicEnabled" :disabled="busy||!!pending||cacheBlocked"/></label><label>公开专业<input v-model="form.publicSpecialty" maxlength="1000" :required="form.publicEnabled" :disabled="busy||!!pending||cacheBlocked"/></label><label>公开介绍<textarea v-model="form.publicIntro" rows="3" maxlength="3000" :required="form.publicEnabled" :disabled="busy||!!pending||cacheBlocked"/></label><label class="b-checkbox"><input v-model="form.publicEnabled" type="checkbox" :disabled="busy||!!pending||cacheBlocked"/><span>明确发布以上字段供患者端显示</span></label></template><template v-else><label>关联诊所<input :value="clinicName(form.clinicId)" readonly/></label><label>有效开始日<input v-model="form.validFrom" type="date" required :readonly="!!form.practiceId" :disabled="busy||!!pending||cacheBlocked"/></label><label>有效结束日（未知可留空）<input v-model="form.validTo" type="date" :disabled="busy||!!pending||cacheBlocked"/></label><p class="b-help">日期含两端。本批今日或未来新增/结束，原开始日固定；不同诊所可关联同一牙医，同店有效期不能重叠。不替代排班处理。</p></template><label>本次核实或变更依据<textarea v-model="form.reason" required rows="2" maxlength="1500" :disabled="busy||!!pending||cacheBlocked"/></label><button type="button" class="b-button outline full" :disabled="busy||!!pending||cacheBlocked" @click="inspect">检查变更影响</button><div v-if="preview" class="dw-preview"><p v-if="!previewCurrent" class="b-alert warning">内容已变化，请重新检查影响。</p><template v-else><strong>未来受影响：排班{{preview.affected.schedules.length}}项，预约{{preview.affected.appointments.length}}项</strong><p class="b-help">预览和保存都不会自动修改这些安排，后续分别由排班与前台联系办理。</p><details v-if="impactCount"><summary>展开影响清单</summary><article v-for="(x,k) in [...preview.affected.schedules.map((s:any)=>({...s,type:'排班'})),...preview.affected.appointments.map((s:any)=>({...s,type:'预约'}))]" :key="k"><strong>{{x.type}} {{short(x.id)}} · {{clinicName(x.clinicId)}}</strong><p>{{time(x.startsAt)}} — {{time(x.endsAt)}} · v{{x.version}}</p></article></details><label v-if="impactCount" class="b-checkbox"><input v-model="form.confirmImpact" type="checkbox" :disabled="busy||!!pending||cacheBlocked"/><span>已核对以上影响，后续由授权岗位处理，不代患者接受改约。</span></label></template></div><label class="b-checkbox"><input v-model="form.checked" type="checkbox" required :disabled="busy||!!pending||cacheBlocked"/><span>已明确核对本分支完整资料及来源，保留其他分支和历史身份。</span></label><button class="b-button full" :disabled="busy||!!pending||cacheBlocked||!previewCurrent||impactCount>0&&!form.confirmImpact"><Save :size="17"/>{{busy?'正在核对…':'确认保存本分支'}}</button></form></div></div></template>
<style scoped>.dw-query{display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;max-width:680px;margin:20px 0}.dw-query label{display:grid;gap:9px;flex:1 1 240px;min-width:0;color:#53675c;font-size:14px}.dw-query input{box-sizing:border-box;width:100%;border:1px solid #dce5dc;border-radius:8px;background:white;padding:12px;font:inherit}.dw-query .b-button{flex:0 0 auto}.dentist-workspace{display:grid;grid-template-columns:minmax(0,1fr);min-width:0;gap:24px}.dw-head,.dw-block{padding:28px}.dw-head,.dw-title{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.dw-head h2,.dw-block h3{display:flex;gap:10px;align-items:center}.dw-head h2{font-size:25px;margin:10px 0}.dw-head p,.dw-title p{color:#798a80;line-height:1.8}.dw-head label,.dw-dialog label{display:grid;gap:9px;font-size:14px;color:#53695c}.dw-head select,.dw-dialog input:not([type=checkbox]),.dw-dialog textarea{padding:12px;font:inherit;border:1px solid #dce5dc;background:white;border-radius:8px;min-width:0}.dw-block h3{margin-top:0}.dw-doctors{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.dw-doctor{display:flex;align-items:center;text-align:left;gap:16px;border:1px solid #e0e9df;background:#fff;padding:18px;border-radius:12px;color:#355c49;font:inherit;cursor:pointer;min-width:0}.dw-doctor.selected{background:#edf6ef;border-color:#528873}.dw-doctor small{display:block;font-size:12px;color:#86978b;margin-top:8px}.dw-avatar{display:grid;place-items:center;border-radius:50%;width:46px;height:46px;background:#e8f1e9;font-size:23px;flex-shrink:0}.dw-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-top:25px}.dw-fields dt{color:#839488;font-size:13px}.dw-fields dd{margin:9px 0 0;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}.dw-tags{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.dw-tags span{border-radius:8px;padding:9px 14px;background:#edf4ed;color:#38705a;font-size:14px}.dw-public{padding:24px;background:#f4f8f1;border-radius:13px;margin:20px 0}.dw-public h3{font-size:25px;margin:20px 0 10px}.dw-public p,.dw-history p{line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}.dw-public p{color:#6a8472}.dw-history{border-top:1px solid #e5eee4;padding:23px 0}.dw-history p{font-size:14px}.dw-history small{font-size:12px;color:#86968c;line-height:1.8}.dw-history pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.dw-dialog{max-width:710px}.dw-dialog>label,.dw-dialog>button{margin-top:18px}.dw-dialog .b-checkbox{display:flex;align-items:flex-start;line-height:1.8}.dw-preview{padding:18px;background:#f2f7f0;border-radius:10px;margin:20px 0}.dw-preview article{font-size:13px;padding:12px 0;border-top:1px solid #dfe9dc}.dw-preview details{max-height:280px;overflow:auto}.dw-block .b-help,.dw-dialog .b-help{line-height:1.9}.dw-head label{min-width:200px}@media(max-width:760px){.dw-head,.dw-block{padding:20px}.dw-head h2{font-size:22px}.dw-doctors,.dw-fields{grid-template-columns:1fr}.dw-title>.b-button,.dw-head>label{width:100%}.dw-public{padding:18px}}</style>
